/* 1. Primeiro criamos a estrutura fixa (a Tabela) */
CREATE TABLE CLIENTES (
    ID INT PRIMARY KEY,
    NOME VARCHAR(100),
    SALDO DECIMAL(10,2)
);

/* 2. Inserimos os dados exatamente onde eles pertencem */
INSERT INTO CLIENTES (ID, NOME, SALDO) 
VALUES (1, 'Maria Silva', 1500.00);

/* 3. Fazemos uma pergunta clara ao banco */
SELECT NOME, SALDO FROM CLIENTES WHERE SALDO > 1000;

/* Você simplesmente joga a informação no banco e ele aceita */
db.clientes.insert({
    "id": 1,
    "nome": "Maria Silva",
    "saldo": 1500.00,
    "time_futebol": "Corinthians"
})

/* 1. Criando uma tabela no DB2 que aceita colunas rígidas e dados flexíveis */
CREATE TABLE COMPRAS_BLACKFRIDAY (
    ID_TRANSACAO INT PRIMARY KEY,
    VALOR DECIMAL(10,2),
    DADOS_DO_RECIBO JSON
);

/* 2. Inserindo o valor com segurança e o recibo com total flexibilidade */
INSERT INTO COMPRAS_BLACKFRIDAY (ID_TRANSACAO, VALOR, DADOS_DO_RECIBO)
VALUES (
    998877, 
    4500.00, 
    '{ 
       "produto": "Smartphone Última Geração", 
       "cor": "Azul Noturno", 
       "entrega": "Expressa",
       "presente": true
     }'
);
